require('dotenv').config();
const { Client } = require('pg');

async function createMissingTables() {
  const client = new Client({
    connectionString: process.env.SUPABASE_DB_URL,
    ssl: { rejectUnauthorized: false }
  });

  await client.connect();

  const candidatesDDL = `
    CREATE TABLE IF NOT EXISTS "candidates" (
      "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
      "slug" VARCHAR(255) NOT NULL,
      "user_id" BIGINT NOT NULL,
      "job_id" BIGINT NOT NULL,
      "name" VARCHAR(255) NOT NULL,
      "email" VARCHAR(255) NOT NULL,
      "phone_number" VARCHAR(255) NOT NULL,
      "resume" VARCHAR(255) NOT NULL,
      "created_at" TIMESTAMPTZ NULL,
      "updated_at" TIMESTAMPTZ NULL
    );
  `;

  const complainsDDL = `
    CREATE TABLE IF NOT EXISTS "complains" (
      "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
      "slug" VARCHAR(255) NOT NULL,
      "user_id" BIGINT NOT NULL,
      "customer_name" VARCHAR(255) NOT NULL,
      "email" VARCHAR(255) NOT NULL,
      "phone" VARCHAR(255) NOT NULL,
      "address" VARCHAR(255) NOT NULL,
      "category" VARCHAR(255) NOT NULL,
      "product_name" VARCHAR(255) NOT NULL,
      "product_serial" VARCHAR(255) NOT NULL,
      "date_of_purchase" VARCHAR(255) NOT NULL,
      "complain_type" VARCHAR(255) NOT NULL,
      "warrenty" VARCHAR(255) NULL,
      "bill_card" VARCHAR(255) NULL,
      "remark" TEXT NULL,
      "created_at" TIMESTAMPTZ NULL,
      "updated_at" TIMESTAMPTZ NULL
    );
  `;

  await client.query(candidatesDDL);
  console.log('✓ Created table candidates in Supabase');

  await client.query(complainsDDL);
  console.log('✓ Created table complains in Supabase');

  await client.end();
}

createMissingTables().catch(console.error);
